Perhatikan pola Method Chaining berikut:
```cpp
class Akumulator {
public:
    int total = 0;
    Akumulator& tambah(int v) {
        total += v;
        return *this;
    }
};
int main() {
    Akumulator a;
    a.tambah(10).tambah(25);
    std::cout << a.total;
    return 0;
}
```
Berapa nilai a.total yang tercetak di layar?

Perhatikan kode polimorfisme berikut:
```cpp
class Induk {
public:
    virtual void sapa() const { std::cout << "Induk"; }
};
class Anak : public Induk {
public:
    void sapa() const override { std::cout << "Anak"; }
};
int main() {
    Anak obj;
    Induk* p = &obj;
    p->sapa();
    return 0;
}
```
Apa teks yang akan dicetak di layar?

